// Base64-encoded copy of assets/images/app_logo_green.png, used to embed the brand
// mark directly in PDFs generated by react-native-html-to-pdf. PDFs are
// rendered without any network or asset-resolution context, so inlining is the
// only reliable way to guarantee the logo appears in the downloaded receipt.
//
// Regenerate with:
//   python3 -c "import base64; print(base64.b64encode(open('assets/images/app_logo_green.png', 'rb').read()).decode())"
const ZEAPER_LOGO_BASE64 = "";

export default ZEAPER_LOGO_BASE64;
